#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXM 100005
#define MAXNODES 200015
#define MAXEDGES 500005
#define INF 1000000000000000000LL

int N, M, K;
int P[MAXM];
int headEdge[MAXM];
int edgeU[MAXM], edgeV[MAXM], edgeNext[MAXM];
int mark[MAXN];
int parent[MAXN], sz[MAXN];
int compMap[MAXN];
int touched[2 * MAXM];
int head[MAXNODES];
int to[MAXEDGES], weight[MAXEDGES], nxt[MAXEDGES];
int ec = 0;

long long dist[MAXNODES];

struct Item {
    long long d;
    int u;
};
struct Item heap[MAXEDGES];
int heapSize = 0;

int find(int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

void add_edge(int u, int v, int w) {
    to[ec] = v;
    weight[ec] = w;
    nxt[ec] = head[u];
    head[u] = ec++;
}

void push(long long d, int u) {
    int i = heapSize++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].d <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].d = d;
    heap[i].u = u;
}

struct Item pop() {
    struct Item ret = heap[0];
    heapSize--;
    if (heapSize > 0) {
        struct Item last = heap[heapSize];
        int i = 0;
        while (1) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            if (left >= heapSize) break;
            int minChild = left;
            if (right < heapSize && heap[right].d < heap[left].d) minChild = right;
            if (heap[minChild].d >= last.d) break;
            heap[i] = heap[minChild];
            i = minChild;
        }
        heap[i] = last;
    }
    return ret;
}

