    scanf("%d %d %d", &N, &M, &K);
    for (int i = 1; i <= K; i++) {
        scanf("%d", &P[i]);
    }
    for (int i = 1; i <= K; i++) {
        headEdge[i] = -1;
    }
    for (int i = 0; i < M; i++) {
        int u, v, t;
        scanf("%d %d %d", &u, &v, &t);
        edgeU[i] = u;
        edgeV[i] = v;
        edgeNext[i] = headEdge[t];
        headEdge[t] = i;
    }
    int A, B;
    scanf("%d %d", &A, &B);

    for (int i = 1; i <= N; i++) {
        mark[i] = 0;
        compMap[i] = 0;
    }
    for (int i = 0; i < MAXNODES; i++) {
        head[i] = -1;
    }
    ec = 0;
    int totalComponents = 0;

    for (int t = 1; t <= K; t++) {
        if (headEdge[t] == -1) continue;
        int touched_count = 0;

        for (int e = headEdge[t]; e != -1; e = edgeNext[e]) {
            int u = edgeU[e];
            int v = edgeV[e];
            if (mark[u] != t) {
                mark[u] = t;
                parent[u] = u;
                sz[u] = 1;
                touched[touched_count++] = u;
            }
            if (mark[v] != t) {
                mark[v] = t;
                parent[v] = v;
                sz[v] = 1;
                touched[touched_count++] = v;
            }
        }

        for (int e = headEdge[t]; e != -1; e = edgeNext[e]) {
            int u = edgeU[e];
            int v = edgeV[e];
            int ru = find(u);
            int rv = find(v);
            if (ru != rv) {
                if (sz[ru] < sz[rv]) {
                    int tmp = ru;
                    ru = rv;
                    rv = tmp;
                }
                parent[rv] = ru;
                sz[ru] += sz[rv];
            }
        }

        for (int i = 0; i < touched_count; i++) {
            int v = touched[i];
            int r = find(v);
            if (compMap[r] == 0) {
                int compNode = N + (++totalComponents);
                compMap[r] = compNode;
            }
            int compNode = compMap[r];
            add_edge(v, compNode, P[t]);
            add_edge(compNode, v, 0);
        }

        for (int i = 0; i < touched_count; i++) {
            int v = touched[i];
            int r = find(v);
            if (compMap[r] != 0) {
                compMap[r] = 0;
            }
        }
    }

    int totalNodes = N + totalComponents;
    for (int i = 1; i <= totalNodes; i++) {
        dist[i] = INF;
    }
    dist[A] = 0;
    heapSize = 0;
    push(0, A);

    while (heapSize > 0) {
        struct Item cur = pop();
        int u = cur.u;
        long long d = cur.d;
        if (d != dist[u]) continue;
        if (u == B) break;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            int w = weight[e];
            if (dist[v] > d + w) {
                dist[v] = d + w;
                push(dist[v], v);
            }
        }
    }

    if (dist[B] >= INF) {
        printf("-1\n");
    } else {
        printf("%lld\n", dist[B]);
    }

    return 0;
}
